  'aiworkspace.demo.quarterly.introText': '2026년 2분기의 일반적인 판매 테이블입니다. 지역과 제품별 매출, 비용, 목표, 전 분기 매출이 들어 있습니다. 데이터 소스 모드에서 숫자를 직접 수정하거나, 캔버스의 위시 블록에 원하는 분석을 한 문장으로 적은 다음 블록의 버튼을 분석, 매크로 작성, 매크로 실행 순서로 세 번 누르세요. 각 단계는 끝나는 즉시 결과를 기록합니다. 마음에 들지 않는 단계가 있으면 이전 탭으로 돌아가 다시 실행하거나 되돌리세요. 파란색 점선 화살표는 위시가 읽는 입력을, 주황색 화살표는 위시가 만든 결과를 가리킵니다. 데이터가 바뀌면 매크로를 다시 실행하세요.',
