  'aiworkspace.demo.film.script.scene3': '3. 저우 영감의 국숫집 · 밤: 저우 영감이 따뜻한 국수 한 그릇을 건네며 소포의 비밀을 털어놓는다. (아처, 저우)',
  'aiworkspace.demo.film.script.scene4': '4. 고가도로 · 밤 · 비: 드론 추격전이 벌어지고, 샤오만이 자석 팔로 아처를 구한다. (아처, 샤오만)',
  'aiworkspace.demo.film.script.scene5': '5. 클라우드톱 타워 꼭대기 · 새벽: 소포를 열자 빛나는 씨앗이 들어 있다. (아처, 샤오만, 저우)',
  'aiworkspace.demo.film.script.scene6': '6. 옥상 · 일출: 도시가 깨어나는 가운데 두 사람이 국수를 먹으며 해돋이를 본다. (아처, 샤오만)',
  'aiworkspace.demo.film.style.summary': '스타일: 사이버펑크 × 수채화, 네온 청록과 보라를 주색으로, 필름 그레인, 16:9 시네마틱 와이드',
  'aiworkspace.demo.film.style.night': '밤 장면은 차가운 색 위주이며, 따뜻한 색은 국숫집과 일출에서만 나온다',
  'aiworkspace.demo.film.style.characters': '캐릭터 디자인은 단순하고 실루엣으로 알아볼 수 있게 한다',
