  'aiworkspace.demo.film.field.outfit': '의상/소품',
  'aiworkspace.demo.film.styleName': '비주얼 스타일',
  'aiworkspace.demo.film.howtoName': '이 캔버스 사용법',
  'aiworkspace.demo.film.howto.title': 'AI 단편 영화 워크플로: 캐릭터 설정 → 캐릭터 이미지 → 스토리보드 → 완성본',
  'aiworkspace.demo.film.howto.text': '왼쪽에서 오른쪽으로 이어지는 생성 흐름이지만, 모든 노드는 일반 캔버스 개체입니다. 왼쪽에는 직접 수정할 수 있는 시나리오, 캐릭터 테이블, 스타일이 있습니다. 각 단계는 위시 블록이며, 카드에서 분석, 매크로 작성, 매크로 실행을 차례로 누르세요. 각 단계는 끝나는 즉시 결과를 기록합니다. 한 단계가 만든 결과가 다음 단계의 입력이 되므로 왼쪽에서 오른쪽 순서로 실행하세요. 파란색 점선 화살표는 위시가 읽는 입력에서 오고, 주황색 화살표는 위시가 만든 결과를 가리킵니다. 캐릭터 테이블이나 시나리오를 수정하면 하위 결과가 오래된 것으로 표시되므로 차례로 다시 실행하세요. 이미지와 영상은 Zone의 AI 모델이 생성합니다.',
  'aiworkspace.demo.film.surface': '단편 영화 워크플로',
  'aiworkspace.demo.film.wish1.title': '위시 블록 ①: 캐릭터 설정 이미지 생성',
  'aiworkspace.demo.film.wish1.prompt': '‘{{characters}}’ 테이블과 ‘{{style}}’을 바탕으로 각 캐릭터의 세로형 설정 이미지를 만들고 짧은 설정 설명을 덧붙여 주세요. 이후 스토리보드에서 참조할 수 있도록 캐릭터마다 주색과 소품 특징을 유지해 주세요.',
  'aiworkspace.demo.film.wish1.output': '캐릭터 설정 이미지',
  'aiworkspace.demo.film.wish2.title': '위시 블록 ②: 스토리보드 생성',
  'aiworkspace.demo.film.wish2.prompt': '‘{{script}}’의 장면 구성을 바탕으로 ‘{{sheets}}’와 ‘{{style}}’을 참고해 스토리보드를 만들어 주세요. 장면마다 샷 하나씩, 샷 목록(샷 번호, 장면, 샷 크기, 등장 캐릭터, 동작, 길이)과 각 샷의 화면을 출력합니다.',
  'aiworkspace.demo.film.wish2.output': '스토리보드',
  'aiworkspace.demo.film.wish3.title': '위시 블록 ③: 완성본 미리보기 생성',
  'aiworkspace.demo.film.wish3.prompt': '‘{{storyboard}}’를 바탕으로 완성본 미리보기 영상을 만들어 주세요. 샷 번호 순서대로 샷을 이어 약 8초 길이의 연속된 클립(16:9)으로 만들고, 첫 번째 샷의 화면을 참조 이미지로 사용합니다. 샷 목록의 샷 수와 총 길이를 알려 주는 설명도 함께 작성해 주세요.',
  'aiworkspace.demo.film.wish3.output': '완성본',
